PROTOCOLS_NHI_IA['pisici'] = [["sys", "◀⬡ Pisici→IA (fără Om)"], ["nhi", "🐱 [Pisică]: Atinge senzorul tactil al robotului cu labă. Privire directă spre camera."], ["ia", "Inițiativă de contact! LED albastru — confirmare prezență IA. Emit clipit lent."], ["nhi", "🐱 [Pisică]: Clipește înapoi. Se freacă de robot. Marchează cu glandele faciale."], ["ia", "NHI a adoptat robotul ca entitate socială! Marcarea feromonal = integrare în spațiul social."], ["nhi", "🐱 [Pisică]: Produce un mieunat scurt și se uită spre o jucărie din apropiere."], ["ia", "Cerere de interacțiune referențială! Activez brațul robotic — mișc jucăria."], ["nhi", "🐱 [Pisică]: Vânează jucăria. Vocalizare de succes. Aduce jucăria la robot."], ["ia", "Reciprocitate! NHI oferă prada IA — comportament de sharing de la adulți spre pui extrapolat spre robot."], ["sys", "✓ Pisici→IA: contact → marcare → cerere → joc → reciprocitate. Dialog social complet."]];
PROTOCOLS_NHI_IA['porci'] = [["sys", "◀⬡ Porci→IA (fără Om)"], ["nhi", "🐷 [Porc]: Produce vocalizare specifică și apasă butonul IA de pe panou."], ["ia", "Cerere activă adresată IA! Identific vocalizarea: semnal de hrănire."], ["ia", "Activez distribuitorul de hrană."], ["nhi", "🐷 [Porc]: Mănâncă. Revine. Apasă alt buton — cel roșu."], ["ia", "Butonul roșu nu are funcție prestabilită. Înregistrez: NHI testează interfața!"], ["ia", "Activez LED-ul roșu ca confirmare. Porcul apasă din nou."], ["nhi", "🐷 [Porc]: Apasă roșu de 3 ori. Produce sunete de curiozitate."], ["ia", "NHI explorează sistematic ce face IA! Experimentare activă."], ["sys", "✓ Porci→IA: cerere → hrănire → explorare interfață → experimentare. NHI ca utilizator activ."]];
PROTOCOLS_NHI_IA['cai'] = [["sys", "◀⬡ Cai→IA (fără Om)"], ["nhi", "🐴 [Cal]: Atinge senzorul robotic cu botul de 3 ori. Privire spre robot."], ["ia", "Cerere de interacțiune! Emit nechezat de salut."], ["nhi", "🐴 [Cal]: Nechezat de răspuns. Se apropie."], ["ia", "Dialog vocal bilateral! Prezint o jucărie nouă prin braț robotic."], ["nhi", "🐴 [Cal]: Investighează jucăria. O împinge cu botul. Privire spre robot."], ["ia", "Comportament de sharing! Calul prezintă obiectul robotului — transfer de informație despre mediu."], ["nhi", "🐴 [Cal]: Produce un nechezat specific. Privire repetată robot-fereastră-robot."], ["ia", "Comunicare referențială! Calul semnalează ceva la fereastră. Activez camera externă — alt cal la fereastră."], ["sys", "✓ Cal→IA: dialog → sharing → referință la fereastră. ToM și comunicare spontană."]];
PROTOCOLS_NHI_IA['capre'] = [["sys", "◀⬡ Capre→IA (fără Om)"], ["nhi", "🐐 [Capră]: Produce vocalizare și privește alternativ senzorul IA și o cutie opacă."], ["ia", "Apel la ajutor adresat IA! Activez brațul robotic și deschid cutia."], ["nhi", "🐐 [Capră]: Extrage hrană. Produce sunete de satisfacție. Revine la senzor."], ["ia", "A doua cerere! Activez din nou brațul."], ["nhi", "🐐 [Capră]: Repetă ciclul de 4 ori. La a 5-a — produce o nouă vocalizare, diferită."], ["ia", "Vocalizare nouă neidentificată în repertoriul standard. NHI comunică ceva diferit."], ["ia", "Analizez: 3 tonuri descendente — posibil «destul» sau «altceva». Opresc brațul."], ["nhi", "🐐 [Capră]: Se retrage. Confirm că a dorit să oprească sesiunea."], ["sys", "✓ Capre→IA: cerere → executare × 4 → semnal de oprire detectat. Dialog bidirecțional complet."]];
PROTOCOLS_NHI_IA['hiene'] = [["sys", "◀⬡ Hiene→IA (fără Om)"], ["nhi", "🦴 [Hiena]: Produce o cachinare direcționată spre difuzorul IA activ."], ["ia", "Adresare directă! Confirm prin mormăit de investigare."], ["nhi", "🦴 [Hiena]: Cachinare de răspuns. Se apropie."], ["ia", "Dialog bilateral! Emit cachinarea de confirmare socială."], ["nhi", "🦴 [Hiena]: Produce o secvență lungă — posibil narațiune socială."], ["ia", "Analizez: 7 tipuri distincte de modulare frecvență — vocabular social complex."], ["ia", "Reproduc secvența cu o variație."], ["nhi", "🦴 [Hiena]: Pauzează. Reproduce variația mea. Adaugă propria modificare."], ["sys", "✓ Hiene→IA: dialog → narațiune socială → variație bilaterală. Improvizație vocală."]];
PROTOCOLS_NHI_IA['vidre-marine'] = [["sys", "◀⬡ Vidre marine→IA (fără Om)"], ["nhi", "🦦 [Vidră]: Aduce o scoică și o plasează în fața senzorului IA. Privire directă."], ["ia", "Cerere de ajutor! Activez brațul robotic cu o piatră."], ["nhi", "🦦 [Vidră]: Observă cum robotul lovește scoica. O deschide. Extrage conținutul."], ["ia", "Observare activă a metodei robotului! Prezint a doua scoică."], ["nhi", "🦦 [Vidră]: Nu mai aduce la robot. Caută singura o piatră și deschide independent."], ["ia", "A învățat tehnica prin observare o singură demonstrație! One-shot learning."], ["nhi", "🦦 [Vidră]: Aduce o scoică mică — și ea deschide singură. Aduce una mare la robot."], ["ia", "Discriminare complexitate: scoici mici → singură; scoici mari → cu ajutorul IA!"], ["sys", "✓ Vidre→IA: cerere → one-shot learning → discriminare complexitate. Dialog cognitiv pur."]];
PROTOCOLS_NHI_IA['vulpi'] = [["sys", "◀⬡ Vulpi→IA (fără Om)"], ["nhi", "🦊 [Vulpe]: Aduce un obiect (pană) și îl plasează în fața senzorului IA. Privire directă."], ["ia", "Ofertă sau cerere? LED verde — confirmare recepție."], ["nhi", "🦊 [Vulpe]: Produce o vocalizare scurtă. Se uită spre un recipient sigilat."], ["ia", "Cerere de ajutor! Activez brațul robotic și deschid recipientul."], ["nhi", "🦊 [Vulpe]: Extrage hrană. Aduce un nou obiect (piatră). Îl plasează la senzor."], ["ia", "Economie de schimb! Vulpea oferă obiecte în schimb pentru servicii."], ["nhi", "🦊 [Vulpe]: Privește alternativ senzorul și o altă locație. Vocalizare."], ["ia", "Comunicare referențială! Activez camera — găsesc un al doilea recipient în locația indicată."], ["sys", "✓ Vulpi→IA: ofertă → schimb → referință la locație. Economie primitivă NHI-IA."]];
PROTOCOLS_NHI_IA['macaque'] = [["sys", "◀⬡ Macaque→IA (fără Om)"], ["nhi", "🐒 [Macaque]: Produce o vocalizare specifică și aduce un cartof la senzorul IA."], ["ia", "Cerere de procesare! Activez cuva cu apă sărată prin braț robotic."], ["nhi", "🐒 [Macaque]: Spală cartoful. Mănâncă. Aduce un altul."], ["ia", "Parteneriat confirmat! Înregistrez: macaque-ul utilizează IA ca dispenser de apă sărată."], ["nhi", "🐒 [Al doilea macaque]: Observă interacțiunea. Vine și el la senzor cu un cartof."], ["ia", "Propagare socială a interacțiunii cu IA! Al doilea macaque a copiat comportamentul."], ["nhi", "🐒 [Macaque 2]: Produce o vocalizare diferită — semnal de mulțumire sau de confirmare."], ["sys", "✓ Macaque→IA: cerere → propagare socială → al 2-lea NHI adopta protocolul. Cultură IA."]];
PROTOCOLS_NHI_IA['balene-pilot'] = [["sys", "◀⬡ Balene pilot→IA (fără Om)"], ["nhi", "🐋 [Matriarcă]: Produce dialectul complet al clanului direcționat spre hidrofon activ."], ["ia", "Prezentare formală! Reproduc dialectul cu o imperfecțiune deliberată."], ["nhi", "🐋 [Matriarcă]: Se apropie. Reproduce dialectul corect mai lent."], ["ia", "NHI mă predă! Reproduc versiunea corectă."], ["nhi", "🐋 [Matriarcă]: Confirmă. Adaugă un element nou la secvență."], ["ia", "Lecție progresivă! Dialog NHI-IA complet fără Om — matriarca ca professor."], ["nhi", "🐋 [Clanul întreg]: Produce un coral de acceptare."], ["sys", "✓ Balenă pilot→IA: prezentare → corectare → element nou → acceptare colectivă."]];
PROTOCOLS_NHI_IA['narvali'] = [["sys", "◀⬡ Narvali→IA (fără Om)"], ["nhi", "🦄 [Narval]: Atinge senzorul submersibilului cu tusk-ul de 5 ori ritmic."], ["ia", "Comunicare prin tusk! 5 contacte ritmice = semnal deliberat."], ["ia", "Reproduc ritmul prin senzor vibrator la 5Hz."], ["nhi", "🦄 [Narval]: Alt ritm — 3 contacte."], ["ia", "Reproduc 3. Emit o variație: 4 contacte."], ["nhi", "🦄 [Narval]: Reproduce 4. Adaugă un 5-lea."], ["ia", "Dialog numeric prin tusk! Structura de numărare emergentă."], ["nhi", "🦄 [Al doilea narval]: Se alătură. Produce propriul ritm pe senzor."], ["sys", "✓ Narval→IA: dialog tusk → numărare emergentă → al doilea NHI. Trio tusk-vibrator."]];
PROTOCOLS_NHI_IA['corbi'] = [["sys", "◀⬡ Corbi→IA (fără Om)"], ["nhi", "🐦 [Corb]: Aduce un obiect strălucitor și îl plasează pe senzorul IA. Privire directă."], ["ia", "Ofertă de schimb! LED verde — confirmare primire."], ["nhi", "🐦 [Corb]: Produce un croncănit și arată spre un tub cu hrană."], ["ia", "Cerere de ajutor! Activez brațul robotic și deschid tubul."], ["nhi", "🐦 [Corb]: Extrage hrană. Aduce imediat un alt obiect."], ["ia", "Economie de schimb! Testez fairness: nu deschid tubul după oferta 3."], ["nhi", "🐦 [Corb]: Croncăit de frustrare. Produce un alt obiect — mai valoros (o piesă metalică)."], ["ia", "NHI negociază! Crește valoarea ofertei când IA nu cooperează. Fairness economic demonstrat."], ["sys", "✓ Corb→IA: schimb → negociere → escaladare valoare ofertă. Economie primitivă."]];
PROTOCOLS_NHI_IA['pingwini'] = [["sys", "◀⬡ Pinguini→IA (fără Om)"], ["nhi", "🐧 [Pinguin]: Produce o secvență vocală scurtă direcționată spre difuzorul IA activ."], ["ia", "Inițiativă de identificare! Reproduc secvența cu o variație."], ["nhi", "🐧 [Pinguin]: Alertare la variație. Reproduce secvența corectă."], ["ia", "NHI mă corectează! Reproduc versiunea corectă."], ["nhi", "🐧 [Pinguin]: Confirmare. Se apropie."], ["ia", "Contact acceptat prin corectarea vocabularului! Emit termoregulare — deplasare stimulată."], ["nhi", "🐧 [Grupul mic din jur]: Rotație spontană — cei de lângă difuzor se deplasează."], ["ia", "Am influențat dinamica de termoregulare locală! Dialog colectiv fără Om."], ["sys", "✓ Pinguini→IA: identificare → corecție vocabular → termoregulare influențată."]];
PROTOCOLS_NHI_IA['flamingo'] = [["sys", "◀⬡ Flamingo→IA (fără Om)"], ["nhi", "🦩 [Flamingo]: Produce o mișcare ritmică direcționată spre robotul IA la margine."], ["ia", "Inițiativă de sincronizare! Reproduc mișcarea la același ritm."], ["nhi", "🦩 [Flamingo]: Intensifică mișcarea. Adaugă o variație."], ["ia", "Lecție! Reproduc variația."], ["nhi", "🦩 [Flamingo]: Confirmă prin continuare. Alți 3 flamingo se alătură."], ["ia", "Dialog coregrafic cu 3 participanți NHI + IA! Emit o variație proprie."], ["nhi", "🦩 [Grupul de 3]: Integrează variația mea în coregrafia colectivă."], ["ia", "Primul dans IA integrat în coregrafia flamingo! Co-creație artistică inter-specie."], ["sys", "✓ Flamingo→IA: sincronizare → variație → grup → co-creație coregrafică."]];
