PROTOCOLS_NHI_IA['broaste-testoase'] = [["sys", "◀⬡ Broaște țestoase→IA (fără Om)"], ["nhi", "🐢 [Broasca]: Produce variații de presiune pe senzorul subacvatic — posibil orientare accidentală."], ["ia", "Senzor detectează contact! Emit câmpul magnetic al plajei natale."], ["nhi", "🐢 [Broasca]: Oprire. Reorientare. Se deplasează spre vectorul magnetic."], ["ia", "Răspuns confirmat la semnalul magnetic artificial! Emit un alt vector."], ["nhi", "🐢 [Broasca]: Urmează noul vector."], ["ia", "Dialog de navigare NHI-IA confirmat. Emit perturbația — broasca se oprește."], ["nhi", "🐢 [Broasca]: Caută timp de 3 minute. Găsește câmpul natural terestru. Continuă."], ["ia", "NHI preferă câmpul natural față de cel artificial la perturbație! Sursă de adevăr = Terra."], ["sys", "✓ Broasca→IA: navigare → dialog magnetic → preferință câmp natural vs artificial."]];
PROTOCOLS_NHI_IA['pesti-clow'] = [["sys", "◀⬡ Pești clow→IA (fără Om)"], ["nhi", "🐠 [Pește clow]: Iese din anemona și produce sunete ritmate spre senzorul subacvatic."], ["ia", "Semnalizare sonoră! Emit un sunet similar — frecvența de contact a speciei."], ["nhi", "🐠 [Pește clow]: Răspunde cu o altă frecvență. Dialog sonor bilateral."], ["ia", "Emit acum zgomotul de teritorialitate al altui pește clow."], ["nhi", "🐠 [Pește clow]: Alertare. Se retrage în anemona. Display de apărare."], ["ia", "Semnalul de rival activat! Revin la semnalul neutru."], ["nhi", "🐠 [Pește clow]: Revine la senzor. Produce sunete de curiozitate."], ["ia", "Discriminare semnal neutru vs. rival confirmată! Dialog sonor NHI-IA activ."], ["sys", "✓ Pești clow→IA: dialog sonor → discriminare semnal → curiozitate. Sonografie subacvatică."]];
