PROTOCOLS_NHI_IA['macaque'] = [["sys", "◀⬡ Macaque→IA (fără Om)"], ["nhi", "🐒 [Macaque]: Produce o vocalizare specifică și aduce un cartof la senzorul IA."], ["ia", "Cerere de procesare! Activez cuva cu apă sărată prin braț robotic."], ["nhi", "🐒 [Macaque]: Spală cartoful. Mănâncă. Aduce un altul."], ["ia", "Parteneriat confirmat! Înregistrez: macaque-ul utilizează IA ca dispenser de apă sărată."], ["nhi", "🐒 [Al doilea macaque]: Observă interacțiunea. Vine și el la senzor cu un cartof."], ["ia", "Propagare socială a interacțiunii cu IA! Al doilea macaque a copiat comportamentul."], ["nhi", "🐒 [Macaque 2]: Produce o vocalizare diferită — semnal de mulțumire sau de confirmare."], ["sys", "✓ Macaque→IA: cerere → propagare socială → al 2-lea NHI adopta protocolul. Cultură IA."]];
PROTOCOLS_NHI_IA['narvali'] = [["sys", "◀⬡ Narvali→IA (fără Om)"], ["nhi", "🦄 [Narval]: Atinge senzorul submersibilului cu tusk-ul de 5 ori ritmic."], ["ia", "Comunicare prin tusk! 5 contacte ritmice = semnal deliberat."], ["ia", "Reproduc ritmul prin senzor vibrator la 5Hz."], ["nhi", "🦄 [Narval]: Alt ritm — 3 contacte."], ["ia", "Reproduc 3. Emit o variație: 4 contacte."], ["nhi", "🦄 [Narval]: Reproduce 4. Adaugă un 5-lea."], ["ia", "Dialog numeric prin tusk! Structura de numărare emergentă."], ["nhi", "🦄 [Al doilea narval]: Se alătură. Produce propriul ritm pe senzor."], ["sys", "✓ Narval→IA: dialog tusk → numărare emergentă → al doilea NHI. Trio tusk-vibrator."]];
