PROTOCOLS_NHI_IA['cioaraGriva'] = [["sys", "◀⬡ Cioară grivă→IA (fără Om)"], ["nhi", "🐦‍⬛ [Cioară grivă]: Aduce un obiect la senzorul IA. Privire directă la cameră."], ["ia", "Ofertă! LED verde — confirmare. Activez distribuitorul de hrană."], ["nhi", "🐦‍⬛ [Cioară grivă]: Ia hrană. Revine cu un alt obiect — mai mic."], ["ia", "Al doilea schimb! Valoarea ofertei calibrată la dimensiunea recompensei?"], ["ia", "Nu activez distribuitorul (test fairness)."], ["nhi", "🐦‍⬛ [Cioară grivă]: Croncănit de frustrare. Aduce un obiect mai mare."], ["ia", "Negociere! NHI escaladează valoarea ofertei când IA nu cooperează — fairness economic activ."], ["nhi", "🐦‍⬛ [Cioară grivă]: Privire directă la cameră IA. Croncănit specific."], ["ia", "Cerere directă adresată IA! Activez distribuitorul. NHI ia hrană și pleacă."], ["sys", "✓ Cioară grivă→IA: schimb → test fairness → negociere → escaladare. Economie cognitivă."]];
