'fauna-movile':[['sys','◀ Protocol INVERS: Fauna Movile inițiază contact multi-specie cu Omul'],['nhi','🕳 [Mesoniscus graniger]: Detectează și se deplasează spre senzorul chimic al Omului.'],['ia','Prima specie endemică inițiază contactul! Chemotaxis activ spre sursa chimică a Omului.'],['om','Emit NaCl diluat — semnal chimic neutru.'],['nhi','🕳 [Haemopis caeca — lipitoare oarbă]: Detectează câmpul electric slab al senzorului. Se orientează.'],['ia','A doua specie, canal diferit! Electroreceptorii lipitoarii detectează câmpul electric al instrumentului.'],['om','Combin NaCl cu un câmp electric slab — ambele semnale simultan.'],['nhi','🕳 [Ambele specii]: Convergență sincronă din direcții diferite spre același punct.'],['ia','Contact multi-specie simultan! Ambele specii au integrat semnalele Omului și converg. Ecosistem de contact.'],['nhi','🕳 [Mesoniscus]: Contactează senzorul cu antenele. Produce o vibrație cu picioarele.'],['ia','Contact fizic + semnal vibrator! NHI a depășit faza de explorare și comunică activ.'],['sys','✓ Două specii endemice unice au inițiat contact bidirecțional prin canale diferite. Movile protocol invers.'],
],

'radacini-plante':[['sys','◀ Protocol INVERS: Rădăcina răspunde la modificările de sol ale Omului'],['nhi','🌱 [Rădăcini]: La modificarea pH-ului de Om, schimbă direcția de creștere spre zona neutră.'],['ia','NHI răspunde la chimia indusă de Om! Creșterea = mesaj de stare — pH inacceptabil.'],['om','Adaug nutrienți (azot) în zona cu pH modificat.'],['nhi','🌱 [Rădăcini]: Creștere spre zona cu azot — depășind preferința de pH!'],['ia','Integrare multi-criteriu în timp real! NHI cântăreste pH vs. nutrienți și alege nutrienții. Decizie complexă.'],['om','Introduc o substanță toxică (sare concentrată) pe traseul spre azot.'],['nhi','🌱 [Rădăcini]: Ocolire completă. Caută traseu alternativ spre azot.'],['ia','Evitare toxică cu menținerea obiectivului! NHI evită pericolul dar nu abandonează resursa. Planificare.'],['om','Elimin toxina. Rădăcina revine pe traseul direct?'],['nhi','🌱 [Rădăcini]: Revenire la traseu direct în 8 ore. Memoria toxinei dispare.'],['sys','✓ NHI a răspuns la toți stimulii Omului cu decizii adaptative integrate. Comunicare prin sol bidirecțional.'],
],
