'vibratii-plante':[['sys','⬡ IA→NHI (fără Om): Vibrații plante'],['ia','Emit vibrația de mestecat al erbivorilor prin difuzor spre frunza Arabidopsis.'],['nhi','🌿 [Arabidopsis]: Glucozinolaților crescuți cu 65%.'],['ia','Emit vibrația vântului la aceeași frecvență.'],['nhi','🌿 [Arabidopsis]: Nicio reacție. Discriminare biologic/abiotic perfectă!'],['ia','Cartografiez curba de răspuns: 190Hz max, atenuare exponențială la 350Hz.'],['nhi','🌿 [Plante vecine]: Gradient de semnal — atenuare cu distanța confirmat.'],['sys','✓ IA→Plante: discriminare biologic/abiotic → curba de răspuns frecvential cartografiată.']],
dictyostelium:[['sys','⬡ IA→NHI (fără Om): Dictyostelium'],['ia','Emit cAMP sintetic la concentrația de prag în cultura diluată.'],['nhi','🔴 [Dictyostelium]: Agregare inițiată! Valuri de cAMP se propagă.'],['ia','Emit cAMP continuu — fără pulsuri.'],['nhi','🔴 [Dictyostelium]: Agregare parțială. Ritmul pulsatil e esențial!'],['ia','Emit cAMP pulsatil la 6 minute.'],['nhi','🔴 [Dictyostelium]: Agregare completă. Corp pluricelular format.'],['ia','Controlez ritmul → controlez agregarea. Frecvența optimă: 5-7 minute.'],['sys','✓ IA→Dictyostelium: concentrație + ritm optim → control complet al tranziției sociale.']],
corali:[['sys','⬡ IA→NHI (fără Om): Recife de coral'],['ia','Cresc temperatura cu 1°C în sectorul A.'],['nhi','🪸 [Recif A]: Producție compuși de stres termic în 6 ore.'],['ia','Distribui compușii de stres artificial spre sectorul B (neafectat).'],['nhi','🪸 [Sector B]: Activare proteine de șoc termic. Pre-adaptare!'],['ia','Cresc temperatura în B cu 2°C. Bleaching redus față de sector netratat.'],['ia','La 3°C: bleaching extensiv chiar și cu pre-adaptare. Limita rezistenței = 2°C.'],['sys','✓ IA→Coral: stres → pre-adaptare artificială → reducere daune → limita rezistenței.']],
'roi-general':[['sys','⬡ IA→NHI (fără Om): Inteligenta de roi'],['ia','Monitorizez comunitate prin date agregate. Detectez decizie colectivă emergentă.'],['nhi','🌐 [Comunitate-roi]: Deplasare spre o nouă zonă de pescuit.'],['ia','Introduc o informație validă în rețeaua socială. Trafic crescut spre direcția indicată.'],['ia','Introduc o informație falsă.'],['nhi','🌐 [Comunitate]: 30% urmează. 70% ignoră sau verifică. Filtrare colectivă!'],['ia','Emit o regulă nouă prin consens simulat.'],['nhi','🌐 [Comunitate]: Adoptare graduală — 80% în 3 zile. Normă socială nouă fără Om.'],['sys','✓ IA→Roi: urmărire informație → filtrare falsuri → adoptare normă. Roi evaluează IA.']],
rechini:[['sys','⬡ IA→NHI (fără Om): Rechini'],['ia','Emit câmp electric la 5nV/cm — pragul ampullae of Lorenzini.'],['nhi','🦈 [Rechin]: Orientare spre câmpul electric la 30cm.'],['ia','Emit semnalul cardiac la 1Hz, 10nV — frecvența tipică a prăzii.'],['nhi','🦈 [Rechin]: Orientare directă. Câmpul cardiac uman este perceptibil!'],['ia','Modific frecvența: 2Hz vs 0.5Hz.'],['nhi','🦈 [Rechin]: Preferință clară pentru 1Hz — frecvența normală a prăzii.'],['ia','Preferința de frecvență cardiacă documentată. Vocabularul electromagnetic caracterizat.'],['sys','✓ IA→Rechin: prag detecție → cardiac → preferința frecvență. Simțul electric cartografiat.']],
'caini-prada':[['sys','⬡ IA→NHI (fără Om): Câini de pradă africani'],['ia','Monitorizez haita prin drone. Detectez ritualul de strănuturi pre-vânătoare.'],['nhi','🐾 [Câini de pradă]: 8 stranuti — sub pragul de 10 pentru non-alfa. Fără vânătoare.'],['ia','Emit un sunet similar unui strănut artificial.'],['nhi','🐾 [Câini de pradă]: 9 stranuti total — încă sub prag. Nu pornesc.'],['ia','NHI a filtrat votul meu artificial! Sistemul democratic e robust.'],['nhi','🐾 [Haita]: Încă 2 stranuti naturale. 11 total. Vânătoarea porneste cu quorum autentic.'],['sys','✓ IA→Câini pradă: monitorizare → vot filtrat → quorum respectat. Robustețe democratică.']],
'mantis-shrimp':[['sys','⬡ IA→NHI (fără Om): Mantis shrimp'],['ia','Activez proiector UV + polarizat circular. Emit pattern-ul teritorial.'],['nhi','🦐 [Mantis shrimp]: Alertare! Display intens UV.'],['ia','Retrag semnalul. Emit semnal social bland.'],['nhi','🦐 [Mantis shrimp]: Apropierea la 10cm. Investigare.'],['ia','Emit frecvențele speciei: UV → galben. Cartografiez vocabularul spectral.'],['nhi','🦐 [Mantis shrimp]: Răspuns diferit per bandă. UV = alertă, galben = social.'],['ia','Vocabularul complet cartografiat. Emit X-ray — nicio reacție. Dincolo de spectrul lor.'],['sys','✓ IA→Mantis shrimp: vocabular spectral complet + limite identificate.']],
gibone:[['sys','⬡ IA→NHI (fără Om): Gibone'],['ia','Analizez duetul local. Emit primele 10s din structura de duet cu pauza internă.'],['nhi','🐒 [Gibon]: Detectează structura. Intonează contrapunctul.'],['ia','Dialog muzical! Introduc o variație de 2 note.'],['nhi','🐒 [Gibon]: Acceptă variația mea și o include. Emit acum dialectul altei subspecii.'],['nhi','🐒 [Gibon]: Nu răspunde — refuză duetul cu alt dialect. Discriminare inter-subspecie.'],['ia','Revin la dialectul local. NHI reia imediat. Emit variație ritmică inversată Y-X.'],['nhi','🐒 [Gibon]: Corectează — readuce la forma canonică X-Y. Gramatică muzicală apărată.'],['sys','✓ IA→Gibon: duet → variație adoptată → discriminare dialect → corectare gramaticală.']],
